function OperationLaboratoryEntry({data,send,openCase}:any){const op=data.operation;if(op.linked_project_id)return <section className="panel"><h2>پرونده متصل به درخواست پذیرش</h2><p>{op.title} · {op.reference}</p><button className="primary" onClick={()=>openCase(op.linked_project_id)}>مشاهده پرونده مادر همین درخواست</button>{data.resources.can_intake&&<a className="primary" href={'/sample-intake?id='+encodeURIComponent(op.linked_project_id)}>پذیرش سه‌مرحله‌ای نمونه همین پرونده</a>}</section>;return <><p className={styles.notice}>این درخواست هنوز به پرونده آزمایشگاهی متصل نیست. ابتدا پرونده موجود را پس از تطبیق هویت انتخاب کنید؛ تنها اگر پرونده وجود ندارد ثبت جدید انجام دهید. اتصال، مجوز اجرا یا تأیید دریافت نمونه نیست.</p><Form title="اتصال به پرونده مادر موجود" button="ثبت ارتباط و مشاهده پرونده" send={async(b:any)=>{const r=await send({...b,action:'case_link_operation',operation_id:op.id,operation_revision:op.revision,identity_confirmed:b.identity_confirmed==='yes'});await openCase(r.id);}}><Select label="پرونده مادر موجود" name="id" required options={data.cases.map((c:any)=>({id:c.id,title:c.invoice_number+' — '+c.customer.name+' — '+c.title}))}/><Field label="تأیید شماره فاکتور پرونده مقصد" name="confirm_invoice" required/><label><input type="checkbox" required name="identity_confirmed" value="yes"/>هویت محقق و شماره فاکتور را تطبیق داده‌ام</label><Area label="مدرک تطبیق هویت و فاکتور" name="identity_reason" required minLength={10}/></Form><details><summary>پرونده موجود نیست — ثبت پرونده جدید همین درخواست</summary><CaseCreate data={data} send={send} done={openCase}/></details></>}
