{tab===0&&<>{!data.user.laboratory&&<p>{c.customer.phone} · {c.customer.email} · {c.customer.organization}</p>}<p>{c.description||'توضیح تکمیلی ثبت نشده است.'}</p>{!c.archived&&['draft','changes'].includes(c.review_state)?<CaseCreate data={data} send={send} done={openCase} draft={{...c,revision:p.revision,draft_form:c.draft_form||{invoice_number:c.invoice_number,customer_name:c.customer.name,customer_phone:c.customer.phone,customer_email:c.customer.email,organization:c.customer.organization,title:c.title,description:c.description,assignments:c.assignments}}}/>:<>{c.can_approve&&data.user.manager&&<Form title="تصمیم مدیریت" button="تأیید و ارجاع سفارش‌ها" send={(b:any)=>act({...b,action:'case_approve'})}><p className={styles.wide}>تأیید، سفارش‌های خدمات انتخاب‌شده را ایجاد می‌کند؛ وصول بانکی یا پذیرش نمونه نیست.</p></Form>}{!c.management_approved&&!c.archived&&data.user.manager&&<Form title="درخواست اصلاح یا رد مستند" button="ثبت تصمیم" send={(b:any)=>act({...b,action:'case_review'})}><Select label="تصمیم" name="decision" required options={[{id:'changes',title:'بازگرداندن برای اصلاح'},{id:'reject',title:'رد با ثبت دلیل'}]}/><Area label="دلیل تصمیم" name="reason" required minLength={5}/></Form>}{selected.resources.can_intake&&!c.archived&&<a className="primary" href={'/sample-intake?id='+encodeURIComponent(p.id)}>پذیرش سه‌مرحله‌ای نمونه همین پرونده</a>}{p.can_edit&&!c.archived&&!data.user.laboratory&&!['draft','changes'].includes(c.review_state)&&<details><summary>ویرایش اطلاعات مدیریتی پرونده موجود</summary><p className="hint">این فیلدها برنامه مدیریتی را ثبت می‌کنند و وضعیت واقعی آزمایشگاه یا مجوز اجرا را تغییر نمی‌دهند. تغییرات در تاریخچه پرونده ثبت می‌شود.</p><Form title="اطلاعات مدیریت پروژه" button="ذخیره اطلاعات مدیریتی" send={(b:any)=>act({...b,action:'case_project_metadata_update'})}><Select label="نوع پروژه" name="project_kind" blank={false} defaultValue={c.research_project?.project_kind||'research'} options={projectKinds}/><Select label="اولویت" name="priority" blank={false} defaultValue={c.research_project?.priority||'normal'} options={projectPriorities}/><Select label="نوع مسئولیت" name="responsibility_type" defaultValue={c.research_project?.responsibility_type||''} options={selectableProjectResponsibilities}/><Select label="فرد مسئول" name="responsibility_person" defaultValue={c.research_project?.responsibility_person||''} options={data.members.filter(memberResponsibility).map((m:any)=>({id:m.id,title:memberResponsibility(m)!}))}/><Select label="نوع تأییدکننده پیشنهادی" name="approver_type" defaultValue={c.research_project?.approver_type||''} options={projectApproverTypes}/><Select label="وضعیت برنامه‌ریزی (مستقل از اجرای واقعی)" name="execution_status" blank={false} defaultValue={c.research_project?.execution_status||'pending_management'} options={projectExecutionStatuses}/><Select label="دلیل مانع" name="blocker_reason" blank={false} defaultValue={c.research_project?.blocker_reason||'none'} options={projectBlockerReasons}/><Field label="شروع پروژه (YYYY-MM-DD)" name="project_start" type="date" value={c.research_project?.project_start||''}/><Field label="موعد پروژه (YYYY-MM-DD)" name="project_due" type="date" value={c.research_project?.project_due||''}/></Form></details>}{p.can_edit&&!c.archived&&<details><summary>ویرایش توضیحات تکمیلی</summary><Form button="ذخیره توضیحات" send={(b:any)=>act({...b,action:'case_update'})}><Area label="شرح پروژه" name="description" value={c.description}/></Form></details>}</>}<p className="hint">اقدام بعدی: {c.can_approve?'بررسی مدیریت و ارجاع':c.status==='پیش‌نویس'?'تکمیل مشخصات و خدمات':!items.length?'ثبت اعلام و دریافت واقعی نمونه از پذیرش':'پیگیری سفارش‌های همین پرونده'}</p></>}
